<style>
  *{margin:0;padding:0;box-sizing:border-box}

  :root{
    --ink:#141414;
    --red:#dc2a1e;
    --blue:#1b3c97;
    --yellow:#f2c230;
    --paper:#f2efe8;
    --white:#fbf8f1;
    --grey:#c9c5bb;
    --line:6px;
  }

  html{scroll-behavior:smooth}

  body{
    background:var(--paper);
    color:var(--ink);
    font-family:'Archivo',system-ui,'Segoe UI',sans-serif;
    font-size:1rem;
    line-height:1.65;
