  .mark i:nth-child(3){background:var(--blue)}
  .mark i:nth-child(4){background:var(--yellow)}
  .head-title{font-size:.95rem;letter-spacing:.12em}
  .head-mid{
    margin-left:auto;font-size:.8rem;font-weight:600;
    letter-spacing:.14em;text-transform:uppercase;color:#bdb8ac;
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  }
  .head-src{
    color:var(--yellow);text-decoration:none;font-weight:700;
    text-transform:uppercase;letter-spacing:.1em;font-size:.8rem;
    border-bottom:3px solid var(--yellow);padding-bottom:2px;
  }
  .head-src:hover{color:#fff;border-color:#fff}

  /* ---------- sheet (framed canvas) ---------- */
  .sheet{
    max-width:1280px;
    margin:clamp(16px,4vw,44px) auto clamp(24px,4vw,48px);
    background:#fff;
    border:8px solid var(--ink);
    box-shadow:16px 16px 0 var(--grey);
  }

  /* ---------- hero ---------- */
  .hero{
    display:grid;
    grid-template-columns:minmax(0,7fr) minmax(0,5fr);
    border-bottom:var(--line) solid var(--ink);
  }
  .hero-text{padding:clamp(28px,5vw,64px)}
  .hero-art{
    border-left:var(--line) solid var(--ink);
    padding:clamp(18px,3vw,34px);
    display:flex;flex-direction:column;justify-content:center;gap:16px;
    background:var(--white);
  }

  .eyebrow{
    display:flex;align-items:center;gap:10px;
    font-size:.82rem;font-weight:700;letter-spacing:.2em;
    text-transform:uppercase;margin-bottom:22px;
  }
  .tri{display:inline-flex;gap:5px}
  .tri i{width:13px;height:13px;display:block;border:2px solid var(--ink)}
  .tri i:nth-child(1){background:var(--red)}
